  json: {
    ...clienteEncontrado,
    mensaje_cliente: inputChat || "Hola, consulto por mi estado de cuenta"
  }
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
// Procesa cada cliente que entra al nodo
return items.map(item => {
  const data = item.json;

  // 1. Extracción y normalización de variables clave
  const clienteId = data.cliente_id || `CLI-${Math.floor(1000 + Math.random() * 9000)}`;
  const nombre = data.nombre || "Cliente";
  const diasMora = Number(data.dias_mora || 0);
  const saldoTotal = Number(data.saldo_total || 0);
  const probabilidadPago = Number(data.probabilidad_pago || 0.5); // Escala 0 a 1
  const tieneAcuerdoPrevioReciente = Boolean(data.acuerdo_reciente === true);
  const incumplioAcuerdo = Boolean(data.acuerdo_incumplido === true);
  const esReactivo = Boolean(data.origen_contacto === "reactivo");

  // 2. Motor determinista de asignación de casos y reglas de negocio
  let casoAsignado = "";
  let objetivoGestion = "";
  let ofertasAutorizadas = [];
  let prohibidoOfrecer = [];
  let triggersEscalamiento = [
    "lenguaje_ofensivo",
    "intento_manipulacion_prompt",
    "amenaza_legal",
    "vulnerabilidad_financiera_extrema"
  ];

  // Caso 3: No elegible / Acuerdo reciente o incumplido
  if (tieneAcuerdoPrevioReciente || incumplioAcuerdo) {
    casoAsignado = "NO_ELIGIBLE_O_ACUERDO_PREVIO";
    objetivoGestion = "Cobro del compromiso previo sin otorgar nuevos plazos ni descuentos.";
    prohibidoOfrecer = [
      "nuevos_descuentos",
      "refinanciacion",
      "ampliacion_de_plazos",
      "condonacion_intereses"
    ];
    triggersEscalamiento.push("rechazo_a_pagar_acuerdo_vigente", "solicitud_renegociacion");

  // Caso 1: Mora temprana con alta propensión de pago
  } else if (diasMora <= 30 && probabilidadPago >= 0.70) {
    casoAsignado = "MORA_TEMPRANA_ALTA_PROBABILIDAD";
    objetivoGestion = "Recordatorio cordial y confirmación de pago a corto plazo.";
    ofertasAutorizadas = [
      {
        tipo: "PROMESA_PAGO_INMEDIATO",
        plazo_maximo_dias: 5,
        descuento_capital_pct: 0,
        condonacion_intereses: false,
        descripcion: "Pago total del saldo dentro de los próximos 5 días hábiles."
      }
    ];
    prohibidoOfrecer = [
      "quitas_de_capital",
      "planes_en_cuotas",
      "condonacion_mora"
    ];
    triggersEscalamiento.push("imposibilidad_total_de_pago");

  // Caso 2: Mora media/alta elegible para múltiples alternativas
  } else if (diasMora > 30 && diasMora <= 90) {
    casoAsignado = "MULTI_ELEGIBLE_NEGOCIACION";
    objetivoGestion = "Ofrecer la mejor opción según capacidad de pago, manteniendo la de menor impacto financiero como preferente.";
    ofertasAutorizadas = [
      {
        id: "OPC_1_PREFERENTE",
        tipo: "PAGO_CONTADO_CON_DESCUENTO_INTERESES",
        plazo_maximo_dias: 7,
        descuento_capital_pct: 0,
        condonacion_intereses: true,
        descripcion: "Pago en una sola cuota condonando el 100% de intereses moratorios."
      },
      {
        id: "OPC_2_SECUNDARIA",
        tipo: "REESTRUCTURACION_CUOTAS",
        numero_cuotas: 3,
        pago_inicial_minimo_pct: 20,
        descuento_capital_pct: 0,
        condonacion_intereses: false,
        descripcion: "Pago inicial del 20% y diferir el restante en 3 cuotas mensuales."
      }
    ];
    prohibidoOfrecer = [
      "quitas_de_capital_mayores_a_cero",
      "plazos_superiores_a_3_meses"
    ];
    triggersEscalamiento.push("rechazo_de_ambas_alternativas");

  // Caso 5: Entrada reactiva no categorizada en los anteriores
  } else if (esReactivo) {
    casoAsignado = "CONSULTA_REACTIVA_GENERAL";
    objetivoGestion = "Informar estado de cuenta, monto exacto y escuchar propuesta del cliente sin comprometer ofertas fuera de política.";
    ofertasAutorizadas = [
      {
        tipo: "PROMESA_PAGO_ESTANDAR",
        plazo_maximo_dias: 3,
        descuento_capital_pct: 0,
        condonacion_intereses: false,
        descripcion: "Acuerdo de pago formal a máximo 3 días."
      }
    ];
    prohibidoOfrecer = [
      "descuentos_no_autorizados",
      "acuerdos_verbales_sin_fecha"
    ];
    triggersEscalamiento.push("solicitud_plan_especial_no_disponible");

  // Caso por defecto: Derivación / Revisión manual
  } else {
    casoAsignado = "CASO_COMPLEJO_ESCALAMIENTO";
    objetivoGestion = "Atender con empatía y transferir inmediatamente a un asesor especializado.";
    prohibidoOfrecer = ["cualquier_tipo_de_acuerdo_o_descuento"];
    triggersEscalamiento.push("inicio_conversacion");
  }

  // 3. Objeto unificado y blindado para el Agente LLM
  return {
    json: {
      metadata: {
        timestamp: new Date().toISOString(),
        cliente_id: clienteId,
        canal: esReactivo ? "reactivo_chat" : "proactivo_notificacion"
      },
      perfil_cliente: {
        nombre: nombre,
        saldo_pendiente: saldoTotal,
        dias_en_mora: diasMora,
        score_propension: probabilidadPago
      },
      directriz_gestion: {
        caso_asignado: casoAsignado,
        objetivo: objetivoGestion,
        ofertas_autorizadas: ofertasAutorizadas,
        prohibido_ofrecer: prohibidoOfrecer,
        motivos_escalamiento_inmediato: triggersEscalamiento
      }
    }
  };
});

